example.programlisting:
$service  = new Zend_Service_SiteVerify($secretKey, Zend_Service_SiteVerify::PROVIDER_RECAPTCHA);
$response = $service->verify($_POST['g-recaptcha-response'], $_SERVER['REMOTE_ADDR']);

if ($response->isSuccess() && $response->getScore() >= 0.5) {
    // reCAPTCHA v3: the token is valid and the score is acceptable
}

$response->getHostname();    // site the challenge was solved on
$response->getAction();      // action name (reCAPTCHA v3, Turnstile)
$response->getErrorCodes();  // e.g. array('timeout-or-duplicate')
$response->toArray();        // the decoded answer of the service
